#include "sima/geometry.hpp"
#include <algorithm>
#include <cmath>
namespace sima {
namespace {double dist(Point a,Point b){return std::hypot(a.x-b.x,a.y-b.y);}double line_dist(Point p,Point a,Point b){double dx=b.x-a.x,dy=b.y-a.y,d=std::hypot(dx,dy);return d<1e-9?dist(p,a):std::abs(dy*p.x-dx*p.y+b.x*a.y-b.y*a.x)/d;}void rdp(const std::vector<Point>&p,std::size_t a,std::size_t b,double e,std::vector<bool>&k){double best=e;std::size_t ix=b;for(std::size_t i=a+1;i<b;++i){double d=line_dist(p[i],p[a],p[b]);if(d>best){best=d;ix=i;}}if(ix!=b){k[ix]=true;rdp(p,a,ix,e,k);rdp(p,ix,b,e,k);}}}
double polygon_area(const std::vector<Point>&p){if(p.size()<3)return 0;double a=0;for(std::size_t i=0;i<p.size();++i){auto q=p[(i+1)%p.size()];a+=p[i].x*q.y-q.x*p[i].y;}return std::abs(a)*.5;}
double perimeter(const std::vector<Point>&p){double s=0;if(p.size()<2)return s;for(std::size_t i=0;i<p.size();++i)s+=dist(p[i],p[(i+1)%p.size()]);return s;}
std::vector<Point> convex_hull(std::vector<Point>p){std::sort(p.begin(),p.end(),[](auto a,auto b){return a.x==b.x?a.y<b.y:a.x<b.x;});p.erase(std::unique(p.begin(),p.end(),[](auto a,auto b){return a.x==b.x&&a.y==b.y;}),p.end());if(p.size()<3)return p;std::vector<Point>h;for(auto q:p){while(h.size()>=2){auto a=h[h.size()-2],b=h.back();if((b.x-a.x)*(q.y-a.y)-(b.y-a.y)*(q.x-a.x)>0)break;h.pop_back();}h.push_back(q);}auto n=h.size();for(auto it=p.rbegin()+1;it!=p.rend();++it){auto q=*it;while(h.size()>n){auto a=h[h.size()-2],b=h.back();if((b.x-a.x)*(q.y-a.y)-(b.y-a.y)*(q.x-a.x)>0)break;h.pop_back();}h.push_back(q);}h.pop_back();return h;}
std::vector<Point> simplify_contour(const std::vector<Point>&p,double e){if(p.size()<4)return p;auto q=p;q.push_back(p.front());std::vector<bool>k(q.size());k.front()=k.back()=true;rdp(q,0,q.size()-1,e,k);std::vector<Point>o;for(std::size_t i=0;i+1<q.size();++i)if(k[i])o.push_back(q[i]);return o.size()>=3?o:p;}
Rect bounds_of(const std::vector<Point>&p){if(p.empty())return{};double ax=p[0].x,bx=ax,ay=p[0].y,by=ay;for(auto q:p){ax=std::min(ax,q.x);bx=std::max(bx,q.x);ay=std::min(ay,q.y);by=std::max(by,q.y);}return{ax,ay,bx-ax,by-ay};}
ShapeMatch classify_shape(const std::vector<Point>&p){if(p.size()<3)return{"unknown",0,1};auto h=convex_hull(p);auto b=bounds_of(h);double a=polygon_area(h),per=perimeter(h),compact=per>0?4*3.141592653589793*a/(per*per):0,aspect=b.height>0?b.width/b.height:1;auto q=simplify_contour(h,std::max(b.width,b.height)*.035);if(compact>.82)return{"ellipse",std::clamp(compact,0.0,1.0),1-compact};if(q.size()==3)return{"triangle",.88,.12};if(q.size()==4&&aspect>.78&&aspect<1.28)return{"quadrilateral",.84,.16};if(q.size()==4)return{"trapezoid",.76,.24};if(q.size()<=7)return{"polygon",.7,.3};return{"freeform",.55,.45};}
std::vector<Point> boundary_points(const Image&m,std::size_t maxp){std::vector<Point>o;if(!m.valid()||m.channels!=1)return o;int step=std::max(1,static_cast<int>(std::sqrt(static_cast<double>(m.width)*m.height/std::max<std::size_t>(maxp,1))));for(int y=1;y<m.height-1;y+=step)for(int x=1;x<m.width-1;x+=step)if(m.at(x,y)>127&&(m.at(x-1,y)<128||m.at(x+1,y)<128||m.at(x,y-1)<128||m.at(x,y+1)<128))o.push_back({static_cast<double>(x),static_cast<double>(y)});return o;}
}
